{
  "name": "FarmaSmart AI",
  "description": "Una plataforma farmacéutica inteligente que combina catálogo de productos con un asistente de salud impulsado por IA para consultas sobre medicamentos y análisis de recetas.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  description: string;
  image: string;
  stock: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export enum AppSection {
  HOME = 'home',
  CATALOG = 'catalog',
  AI_CONSULTANT = 'ai_consultant',
  SCANNER = 'scanner',
  CART = 'cart'
}

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getHealthAdvice = async (message: string, history: { role: string; text: string }[]): Promise<string> => {
  try {
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: `Eres un asistente farmacéutico experto llamado FarmaSmart AI. 
        Tu objetivo es ayudar a los clientes con dudas sobre medicamentos, dosis comunes y bienestar general. 
        IMPORTANTE: Siempre incluye un descargo de responsabilidad indicando que no eres un médico y que deben consultar a un profesional antes de tomar decisiones de salud. 
        Responde de forma profesional, empática y clara en español.`,
      },
    });

    const response = await chat.sendMessage({ message });
    return response.text || "Lo siento, no pude procesar tu solicitud.";
  } catch (error) {
    console.error("Gemini Advice Error:", error);
    return "Error al conectar con el asistente de salud.";
  }
};

export const analyzePrescription = async (base64Image: string): Promise<string> => {
  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image,
            },
          },
          {
            text: `Analiza esta imagen de una receta médica o empaque de medicamento. 
            Identifica el nombre del medicamento, la dosis sugerida y cualquier instrucción relevante. 
            Presenta la información en un formato de lista claro. 
            Si la imagen no es legible o no parece una receta, infórmalo educadamente.`
          }
        ]
      },
    });
    return response.text || "No se pudo extraer información de la imagen.";
  } catch (error) {
    console.error("Gemini Vision Error:", error);
    return "Error al analizar la receta.";
  }
};

import React, { useState, useMemo } from 'react';
import { AppSection, Product, CartItem } from './types';
import { PRODUCTS } from './constants';
import Header from './components/Header';
import HomeSection from './components/HomeSection';
import CatalogSection from './components/CatalogSection';
import AIConsultant from './components/AIConsultant';
import PrescriptionScanner from './components/PrescriptionScanner';
import CartModal from './components/CartModal';

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState<AppSection>(AppSection.HOME);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const cartCount = useMemo(() => cart.reduce((acc, item) => acc + item.quantity, 0), [cart]);

  return (
    <div className="min-h-screen flex flex-col">
      <Header 
        activeSection={activeSection} 
        onNavigate={setActiveSection} 
        cartCount={cartCount} 
        onOpenCart={() => setIsCartOpen(true)}
      />

      <main className="flex-grow pt-20 pb-12">
        {activeSection === AppSection.HOME && <HomeSection onNavigate={setActiveSection} onAddToCart={addToCart} />}
        {activeSection === AppSection.CATALOG && <CatalogSection onAddToCart={addToCart} />}
        {activeSection === AppSection.AI_CONSULTANT && <AIConsultant />}
        {activeSection === AppSection.SCANNER && <PrescriptionScanner />}
      </main>

      <footer className="bg-slate-900 text-white py-12 px-6">
        <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-8 text-center md:text-left">
          <div>
            <h3 className="text-xl font-bold mb-4 text-emerald-400">FarmaSmart AI</h3>
            <p className="text-slate-400">Tu bienestar es nuestra prioridad. Tecnología avanzada al servicio de tu salud.</p>
          </div>
          <div>
            <h4 className="font-semibold mb-4">Secciones</h4>
            <ul className="space-y-2 text-slate-400">
              <li><button onClick={() => setActiveSection(AppSection.HOME)}>Inicio</button></li>
              <li><button onClick={() => setActiveSection(AppSection.CATALOG)}>Productos</button></li>
              <li><button onClick={() => setActiveSection(AppSection.AI_CONSULTANT)}>Consultas IA</button></li>
            </ul>
          </div>
          <div>
            <h4 className="font-semibold mb-4">Contacto</h4>
            <p className="text-slate-400 text-sm">Calle Salud 123, Madrid, España</p>
            <p className="text-slate-400 text-sm">Tel: +34 900 000 000</p>
            <p className="text-emerald-400 text-sm mt-2">Abierto 24/7</p>
          </div>
        </div>
        <div className="mt-12 pt-8 border-t border-slate-800 text-center text-slate-500 text-xs">
          © 2024 FarmaSmart AI. Este sitio utiliza inteligencia artificial. Siempre consulte a su médico.
        </div>
      </footer>

      {isCartOpen && (
        <CartModal 
          cart={cart} 
          onClose={() => setIsCartOpen(false)} 
          onRemove={removeFromCart} 
          onUpdate={updateQuantity} 
        />
      )}
    </div>
  );
};

export default App;

