  );
};

export default CatalogSection;

import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage } from '../types';
import { getHealthAdvice } from '../services/geminiService';

const AIConsultant: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: '¡Hola! Soy tu asistente de salud FarmaSmart. ¿En qué puedo ayudarte hoy? Puedes preguntarme sobre dosis de medicamentos, efectos secundarios comunes o consejos de bienestar.' }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || isLoading) return;

    const userMessage = inputValue.trim();
    setInputValue('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    const response = await getHealthAdvice(userMessage, messages);
    setMessages(prev => [...prev, { role: 'model', text: response }]);
    setIsLoading(false);
  };

  return (
    <div className="max-w-4xl mx-auto px-4 h-[calc(100vh-160px)] flex flex-col py-4">
      <div className="flex items-center gap-4 mb-6">
        <div className="bg-emerald-500 p-3 rounded-2xl text-white shadow-lg shadow-emerald-500/20">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
          </svg>
        </div>
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Asistente Farmacéutico Inteligente</h2>
          <p className="text-sm text-slate-500">Disponible 24/7 para tus consultas de salud.</p>
        </div>
      </div>

      <div className="flex-grow bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden flex flex-col">
        <div className="flex-grow overflow-y-auto p-6 space-y-6">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] rounded-2xl px-5 py-4 ${
                msg.role === 'user' 
                ? 'bg-slate-900 text-white rounded-br-none shadow-md' 
                : 'bg-slate-100 text-slate-800 rounded-bl-none'
              }`}>
                <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</p>
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-slate-100 rounded-2xl px-5 py-4 rounded-bl-none flex items-center gap-2">
                <span className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></span>
                <span className="w-2 h-2 bg-slate-400 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                <span className="w-2 h-2 bg-slate-400 rounded-full animate-bounce [animation-delay:0.4s]"></span>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100">
          <form onSubmit={handleSubmit} className="relative">
            <input 
              type="text" 
              placeholder="Escribe tu consulta aquí..."
              className="w-full pl-6 pr-16 py-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              disabled={isLoading}
            />
            <button 
              type="submit"
              disabled={!inputValue.trim() || isLoading}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-emerald-500 text-white rounded-xl hover:bg-emerald-600 transition-colors disabled:opacity-50"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
              </svg>
            </button>
          </form>
          <p className="text-[10px] text-slate-400 mt-4 text-center">
            * Este asistente es solo informativo. Nunca sustituye el consejo de un profesional médico colegiado.
          </p>
        </div>
      </div>
    </div>
  );
};

export default AIConsultant;

import React, { useState } from 'react';
import { analyzePrescription } from '../services/geminiService';

const PrescriptionScanner: React.FC = () => {
  const [image, setImage] = useState<string | null>(null);
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setImage(base64String);
        setAnalysis(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const startAnalysis = async () => {
    if (!image) return;
    setIsAnalyzing(true);
    const base64Data = image.split(',')[1];
    const result = await analyzePrescription(base64Data);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8 animate-fade-in">
      <div className="text-center mb-12">
        <h2 className="text-3xl font-bold text-slate-900 mb-4">Analizador de Recetas Digital</h2>
        <p className="text-slate-500 max-w-xl mx-auto">
          ¿No entiendes la letra de tu receta? Sube una foto y nuestra IA te ayudará a identificar los medicamentos e indicaciones.
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* Upload Section */}
        <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center min-h-[400px]">
          {image ? (
            <div className="relative w-full h-full flex flex-col items-center">
              <img src={image} alt="Prescription" className="max-h-64 rounded-2xl mb-6 shadow-lg object-contain" />
              <div className="flex gap-4 w-full">
                <button 
                  onClick={() => setImage(null)}
                  className="flex-grow py-3 bg-slate-100 text-slate-600 font-bold rounded-2xl hover:bg-slate-200 transition-colors"
                >
                  Cambiar Imagen
                </button>
                <button 
                  onClick={startAnalysis}
                  disabled={isAnalyzing}
                  className="flex-grow py-3 bg-emerald-500 text-white font-bold rounded-2xl hover:bg-emerald-600 transition-all flex items-center justify-center gap-2"
                >
                  {isAnalyzing ? (
                    <>
                      <span className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></span>
                      Analizando...
                    </>
                  ) : 'Analizar Receta'}
                </button>
              </div>
            </div>
          ) : (
            <label className="w-full h-full flex flex-col items-center justify-center cursor-pointer group border-2 border-dashed border-slate-200 rounded-3xl p-12 hover:border-emerald-500 hover:bg-emerald-50/50 transition-all">
