import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from "../types";

/**
 * Servicio para obtener consejos de salud interactuando con Gemini.
 * @param prompt - El mensaje actual del usuario.
 * @param history - El historial de la conversación previa.
 */
export const getHealthAdvice = async (prompt: string, history: ChatMessage[]): Promise<string> => {
  // Inicialización del cliente de Google GenAI
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Preparar el contenido incluyendo el historial para mantener el contexto
  const contents = [
    ...history.map(msg => ({
      role: msg.role,
      parts: [{ text: msg.text }]
    })),
    {
      role: 'user',
      parts: [{ text: prompt }]
    }
  ];

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: contents,
      config: {
        systemInstruction: "Eres FarmaSmart, un asistente farmacéutico virtual. Proporciona información útil y profesional sobre salud y medicamentos. Siempre termina indicando que esta información es orientativa y el usuario debe consultar a un médico.",
      },
    });

    // Retornar el texto generado por el modelo
    return response.text || "No se pudo generar una respuesta.";
  } catch (error) {
    console.error("Error en getHealthAdvice:", error);
    return "Lo siento, ha ocurrido un error al procesar tu consulta de salud.";
  }
};

/**
 * Analiza una imagen de una receta médica utilizando visión por computadora de Gemini.
 * @param base64Image - Los datos de la imagen en formato base64.
 */
export const analyzePrescription = async (base64Image: string): Promise<string> => {
  // Inicialización del cliente de Google GenAI
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image,
            },
          },
          {
            text: "Analiza esta receta médica. Extrae los nombres de los medicamentos, dosis e instrucciones. Indica si alguna parte es ilegible.",
          },
        ],
      },
    });

    // Retornar el texto extraído y analizado
    return response.text || "No se detectó información en la receta.";
  } catch (error) {
    console.error("Error en analyzePrescription:", error);
    return "Error al analizar la imagen de la receta. Asegúrate de que sea clara y nítida.";
  }
};

