        <button 
          onClick={onSuccess}
          className="w-full bg-slate-900 text-white font-bold py-4 rounded-2xl hover:bg-emerald-600 transition-all shadow-xl"
        >
          Volver al Inicio
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 animate-fade-in">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-12 items-start">
        {/* Lado Izquierdo: Resumen */}
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
          <h3 className="text-xl font-bold mb-6">Resumen de tu pedido</h3>
          <div className="space-y-4 mb-8">
            {cart.map(item => (
              <div key={item.id} className="flex justify-between text-sm">
                <span className="text-slate-600">{item.quantity}x {item.name}</span>
                <span className="font-bold">{(item.price * item.quantity).toFixed(2)}€</span>
              </div>
            ))}
          </div>
          <div className="pt-6 border-t border-slate-100">
            <div className="flex justify-between items-center">
              <span className="text-lg font-bold">Total a pagar</span>
              <span className="text-3xl font-black text-emerald-600">{total.toFixed(2)}€</span>
            </div>
          </div>
          <button 
            onClick={onCancel}
            className="mt-8 text-slate-400 hover:text-slate-600 text-sm font-medium transition-colors"
          >
            ← Volver al catálogo
          </button>
        </div>

        {/* Lado Derecho: Verificación */}
        <div className="bg-slate-900 text-white p-10 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
          <div className="relative z-10">
            <div className="bg-emerald-500 w-12 h-12 rounded-xl flex items-center justify-center mb-6">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
              </svg>
            </div>

            <h2 className="text-2xl font-bold mb-2">Verificación de Seguridad</h2>
            <p className="text-slate-400 text-sm mb-8">Por tu seguridad y para garantizar la entrega, necesitamos verificar tu correo electrónico.</p>

            {step === 'email' ? (
              <form onSubmit={handleSendEmail} className="space-y-6">
                <div>
                  <label className="block text-xs font-bold uppercase tracking-widest text-slate-500 mb-2">Tu Correo Electrónico</label>
                  <input 
                    type="email" 
                    required
                    placeholder="ejemplo@correo.com"
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition-all"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                  />
                </div>
                <button 
                  type="submit"
                  disabled={isLoading}
                  className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-4 rounded-2xl transition-all flex items-center justify-center gap-2 disabled:opacity-50"
                >
                  {isLoading ? (
                    <span className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></span>
                  ) : 'Enviar código de acceso'}
