                    maxLength={6}
                    required
                    placeholder="· · · · · ·"
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white text-center text-2xl tracking-[0.5em] outline-none focus:border-emerald-500 transition-all font-mono"
                    value={code}
                    onChange={(e) => setCode(e.target.value)}
                  />
                </div>
                <button 
                  type="submit"
                  disabled={isLoading || code.length < 4}
                  className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-4 rounded-2xl transition-all flex items-center justify-center gap-2 disabled:opacity-50"
                >
                  {isLoading ? (
                    <span className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></span>
                  ) : 'Verificar y Confirmar Pago'}
                </button>
                <button 
                  type="button"
                  onClick={() => setStep('email')}
                  className="w-full text-slate-500 text-xs hover:text-white transition-colors"
                >
                  Cambiar correo electrónico
                </button>
              </form>
            )}
          </div>

          {/* Decoración de fondo */}
          <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-emerald-500/10 rounded-full blur-3xl"></div>
          <div className="absolute bottom-0 left-0 -ml-16 -mb-16 w-48 h-48 bg-blue-500/10 rounded-full blur-3xl"></div>
        </div>
      </div>
    </div>
  );
};

