import React, { useState, useEffect } from 'react';
import { CartItem } from '../types';

interface VerificationSectionProps {
  cart: CartItem[];
  onSuccess: () => void;
  onCancel: () => void;
}

const VerificationSection: React.FC<VerificationSectionProps> = ({ cart, onSuccess, onCancel }) => {
  const [step, setStep] = useState<'email' | 'code' | 'success'>('email');
  const [email, setEmail] = useState('');
  const [inputCode, setInputCode] = useState('');
  const [generatedCode, setGeneratedCode] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(false);
  const [showToast, setShowToast] = useState(false);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  // Efecto para ocultar el toast automáticamente
  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(false), 8000);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  const handleSendEmail = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;

    setIsLoading(true);
    setError(false);

    // Simulación de proceso de envío
    setTimeout(() => {
      const newCode = Math.floor(100000 + Math.random() * 900000).toString();
      setGeneratedCode(newCode);
      setIsLoading(false);
      setStep('code');
      setShowToast(true); // Mostrar la simulación de correo recibido
    }, 1800);
  };

  const handleVerifyCode = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(false);

    setTimeout(() => {
      if (inputCode === generatedCode) {
        setStep('success');
      } else {
        setError(true);
        setIsLoading(false);
        // Efecto de vibración simple se puede manejar con CSS
      }
    }, 1200);
  };

  if (step === 'success') {
    return (
      <div className="max-w-md mx-auto py-20 px-4 text-center animate-fade-in">
        <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner">
