        <h2 className="text-4xl font-black text-slate-900 mb-4">¡Compra Exitosa!</h2>
        <p className="text-slate-500 mb-10 text-lg">Tu identidad ha sido verificada correctamente. Hemos enviado el comprobante a <span className="font-bold text-slate-700">{email}</span>.</p>
        <button 
          onClick={onSuccess}
          className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-5 rounded-2xl transition-all shadow-xl shadow-emerald-500/20 transform hover:-translate-y-1"
        >
          Volver a la tienda
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto px-4 py-12 animate-fade-in relative">

      {/* Toast de Simulación de Correo */}
      {showToast && (
        <div className="fixed top-24 right-4 z-[110] animate-slide-in-right">
          <div className="bg-slate-900 text-white p-5 rounded-2xl shadow-2xl border border-white/10 max-w-sm flex gap-4 items-start">
            <div className="bg-emerald-500 p-2 rounded-lg shrink-0">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path d="M2.003 5.884L10 9.882l7.997-3.998A2 2 0 0016 4H4a2 2 0 00-1.997 1.884z" />
                <path d="M18 8.118l-8 4-8-4V14a2 2 0 002 2h12a2 2 0 002-2V8.118z" />
              </svg>
            </div>
            <div>
              <p className="font-bold text-sm mb-1">Nuevo mensaje de FarmaSalud</p>
              <p className="text-xs text-slate-400 mb-2">Tu código de verificación es:</p>
              <p className="text-xl font-mono font-black text-emerald-400 tracking-widest bg-white/5 p-2 rounded-lg text-center">
                {generatedCode}
              </p>
            </div>
            <button onClick={() => setShowToast(false)} className="text-slate-500 hover:text-white">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
              </svg>
            </button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-12 items-start">
        {/* Resumen del Pedido (2 cols) */}
        <div className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm sticky top-24">
          <div className="flex items-center gap-3 mb-8">
