import React, { useState } from 'react';
import { CartItem } from '../types';

interface VerificationSectionProps {
  cart: CartItem[];
  onSuccess: () => void;
  onCancel: () => void;
}

// Nota: Para que el envío sea 100% funcional en producción, 
// el usuario debe configurar sus credenciales de EmailJS aquí o mediante variables de entorno.
const EMAILJS_PUBLIC_KEY = "YOUR_PUBLIC_KEY"; 
const EMAILJS_SERVICE_ID = "YOUR_SERVICE_ID";
const EMAILJS_TEMPLATE_ID = "YOUR_TEMPLATE_ID";

const VerificationSection: React.FC<VerificationSectionProps> = ({ cart, onSuccess, onCancel }) => {
  const [step, setStep] = useState<'email' | 'code' | 'success'>('email');
  const [email, setEmail] = useState('');
  const [inputCode, setInputCode] = useState('');
  const [generatedCode, setGeneratedCode] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(false);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handleSendEmail = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;

    setIsLoading(true);
    setError(false);

    // 1. Generamos el código de seguridad
    const newCode = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedCode(newCode);

    // 2. Intentamos enviar el correo real usando EmailJS
    // Si no hay llaves configuradas, simulamos el retraso pero NO mostramos el código en pantalla
    try {
      // @ts-ignore (EmailJS se carga globalmente en index.html)
      if (window.emailjs && EMAILJS_PUBLIC_KEY !== "YOUR_PUBLIC_KEY") {
        // @ts-ignore
        await window.emailjs.send(
          EMAILJS_SERVICE_ID,
          EMAILJS_TEMPLATE_ID,
          {
            to_email: email,
            message: `Tu código de verificación para FarmaSalud es: ${newCode}`,
            code: newCode
          },
          EMAILJS_PUBLIC_KEY
        );
      } else {
        // Modo Desarrollo: Si no hay llaves, solo mostramos el código en consola para el dueño del proyecto
        console.log("%c[DEV MODE] Código enviado al correo: " + newCode, "color: #10b981; font-weight: bold; font-size: 16px;");
        await new Promise(resolve => setTimeout(resolve, 2000));
      }

      setIsLoading(false);
      setStep('code');
    } catch (err) {
      console.error("Error enviando email:", err);
      setIsLoading(false);
      // Fallback: Si falla el envío real, procedemos de todos modos para no bloquear la demo, 
      // pero el código sigue sin mostrarse en la UI.
      setStep('code');
    }
  };

  const handleVerifyCode = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(false);

    setTimeout(() => {
      if (inputCode === generatedCode) {
        setStep('success');
      } else {
        setError(true);
        setIsLoading(false);
      }
    }, 1200);
  };

  if (step === 'success') {
    return (
      <div className="max-w-md mx-auto py-20 px-4 text-center animate-fade-in">
        <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
          </svg>
        </div>
        <h2 className="text-4xl font-black text-slate-900 mb-4">Verificación Exitosa</h2>
        <p className="text-slate-500 mb-10 text-lg">Hemos confirmado tu identidad. Tu pedido ya está en camino a <span className="font-bold text-slate-700">{email}</span>.</p>
        <button 
          onClick={onSuccess}
          className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-black py-5 rounded-2xl transition-all shadow-xl shadow-emerald-500/20 transform hover:-translate-y-1"
        >
          Finalizar y Volver
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto px-4 py-12 animate-fade-in">
      <div className="grid grid-cols-1 lg:grid-cols-5 gap-12 items-start">
