                   <div className="flex justify-between items-start mb-12">
                      <div className="w-12 h-10 bg-amber-400/20 rounded-lg border border-amber-400/30"></div>
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white/20" fill="currentColor" viewBox="0 0 24 24">
                        <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8z"/>
                      </svg>
                   </div>
                   <p className="text-2xl font-mono tracking-[0.2em] text-white/90 mb-8">
                     {cardData.number || "**** **** **** ****"}
                   </p>
                   <div className="flex justify-between">
                     <div>
                       <p className="text-[10px] text-white/40 uppercase tracking-widest">Titular</p>
                       <p className="font-bold tracking-wider">{cardData.name || "NOMBRE APELLIDO"}</p>
                     </div>
                     <div className="text-right">
                       <p className="text-[10px] text-white/40 uppercase tracking-widest">Expira</p>
                       <p className="font-bold tracking-wider">{cardData.expiry || "MM/YY"}</p>
                     </div>
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <input 
                    type="text" required placeholder="Número de Tarjeta"
                    className="w-full bg-white/5 border border-white/10 rounded-xl py-4 px-6 outline-none focus:border-emerald-500"
                    onChange={(e) => setCardData({...cardData, number: e.target.value.replace(/\d{4}(?=.)/g, '$& ')})}
                    maxLength={19}
                  />
                  <input 
                    type="text" required placeholder="Nombre en Tarjeta"
                    className="w-full bg-white/5 border border-white/10 rounded-xl py-4 px-6 outline-none focus:border-emerald-500"
                    onChange={(e) => setCardData({...cardData, name: e.target.value.toUpperCase()})}
                  />
                  <input 
                    type="text" required placeholder="MM/YY"
                    className="w-full bg-white/5 border border-white/10 rounded-xl py-4 px-6 outline-none focus:border-emerald-500"
